<?php
namespace App\Console\Commands;use App\Models\Vaccination;use App\Services\SmsService;use Illuminate\Console\Command;
class SendVaccinationReminders extends Command{protected $signature='medical:vaccination-reminders';protected $description='Notify guardians about vaccinations due within seven days';public function handle():int{$count=0;Vaccination::with('student.student.guardian')->whereNotNull('next_due_date')->whereBetween('next_due_date',[today(),today()->addDays(7)])->where(fn($q)=>$q->whereNull('reminder_sent_at')->orWhere('reminder_sent_at','<',now()->subDays(7)))->each(function($v)use(&$count){$student=$v->student?->student;$phone=$student?->guardian?->father_phone;if($phone&&SmsService::send($phone,"Vaccination reminder: {$student->first_name} {$student->last_name}'s {$v->vaccine_name} ({$v->dose_number}) is due on {$v->next_due_date->format('d M Y')}.",['category'=>'medical','reference_key'=>'vaccination:'.$v->id.':'.$v->next_due_date->format('Y-m-d')])){$v->update(['reminder_sent_at'=>now()]);$count++;}});$this->info("{$count} vaccination reminders sent.");return self::SUCCESS;}}
